// Original calibration: the manual describes population/age behavior, not these rates.
export const CENSUS_AGES=['0–14','15–24','25–34','35–44','45–54','55–64','65–74','75+'];
export const INITIAL_CENSUS_SHARES=[.18,.13,.16,.15,.13,.11,.08,.06];
const ARRIVALS=[.18,.18,.22,.18,.11,.07,.04,.02],ANNUAL_MORTALITY=[.001,.0005,.001,.0015,.003,.008,.025,.09];
const sum=a=>a.reduce((s,n)=>s+n,0);
export const freshDemographics=(population,month)=>({month,cohorts:INITIAL_CENSUS_SHARES.map(w=>population*w),flows:null});
function reconcile(cohorts,population){const total=sum(cohorts),difference=population-total,arrivals=Math.max(0,difference),departures=Math.max(0,-difference);return{cohorts:difference>=0?cohorts.map((n,i)=>n+arrivals*ARRIVALS[i]):cohorts.map(n=>total?n*population/total:0),arrivals,departures};}
export function advanceDemographics(c){
 const d=c.demographics;if(d.month>=c.month)return;
 const startPopulation=sum(d.cohorts),health=Math.pow(2,(59-Math.max(45,Math.min(90,c.stats.lifeExpectancy||59)))/15),survivors=d.cohorts.map((n,i)=>n*(1-ANNUAL_MORTALITY[i]*health/12)),deaths=startPopulation-sum(survivors),births=(survivors[2]+survivors[3])*.032/12;
 const out=survivors.map((n,i)=>i===7?0:n/(i===0?180:120)),aged=survivors.map((n,i)=>n-out[i]+(i?out[i-1]:births)),next=reconcile(aged,c.stats.population);
 c.demographics={month:c.month,cohorts:next.cohorts,flows:{startPopulation,births,deaths,arrivals:next.arrivals,departures:next.departures,endPopulation:c.stats.population}};
 // Transient movement ledger: education consumes these same people counts once.
 return {survivors,out,births,aged,arrivals:ARRIVALS.map(w=>next.arrivals*w)};
}
export function populationCohorts(c,population=c.stats.population){const d=c.demographics||freshDemographics(population,c.month);return reconcile(d.cohorts,population).cohorts;}
export function populationCensus(c){const d=c.demographics||freshDemographics(c.stats.population,c.month),projected=reconcile(d.cohorts,c.stats.population),exact=projected.cohorts,counts=exact.map(Math.floor),remaining=c.stats.population-sum(counts);const order=exact.map((n,i)=>({i,f:n-counts[i]})).sort((a,b)=>b.f-a.f||a.i-b.i);for(let i=0;i<remaining;i++)counts[order[i].i]++;return{month:d.month,total:c.stats.population,flows:d.flows,pendingChange:c.stats.population-sum(d.cohorts),rows:CENSUS_AGES.map((age,i)=>({age,people:counts[i],percent:c.stats.population?counts[i]/c.stats.population*100:0}))};}
export function validateDemographics(v,month){const valid=n=>Number.isFinite(n)&&n>=0&&n<=1e9;if(!v||!Number.isInteger(v.month)||v.month<0||v.month>month||!Array.isArray(v.cohorts)||v.cohorts.length!==8||!v.cohorts.every(valid)||sum(v.cohorts)>1e9)throw Error('Invalid population census.');let flows=null;if(v.flows!==null){const keys=['startPopulation','births','deaths','arrivals','departures','endPopulation'];if(!v.flows||!keys.every(k=>valid(v.flows[k])))throw Error('Invalid population movement record.');flows=Object.fromEntries(keys.map(k=>[k,v.flows[k]]));if(Math.abs(flows.startPopulation+flows.births-flows.deaths+flows.arrivals-flows.departures-flows.endPopulation)>1e-5||Math.abs(sum(v.cohorts)-flows.endPopulation)>1e-5||flows.deaths>flows.startPopulation)throw Error('Population census does not balance.');}return{month:v.month,cohorts:[...v.cohorts],flows};}
export function censusReport(c){const census=populationCensus(c),f=census.flows,fmt=n=>n.toLocaleString('en-US',{maximumFractionDigits:1});return `<details><summary>Population · age census and movement</summary><p>${census.total.toLocaleString()} residents by age.</p><div class="table-scroll"><table><thead><tr><th>Age</th><th>Residents</th><th>Share</th></tr></thead><tbody>${census.rows.map(r=>`<tr><td>${r.age}</td><td>${r.people.toLocaleString()}</td><td><meter min="0" max="100" value="${r.percent}" aria-label="${r.age} population share"></meter> ${fmt(r.percent)}%</td></tr>`).join('')}</tbody></table></div>${f?`<p>Recorded month ${census.month}: ${fmt(f.births)} births · ${fmt(f.deaths)} deaths · ${fmt(f.arrivals)} arrivals · ${fmt(f.departures)} departures. Population changed from ${fmt(f.startPopulation)} to ${fmt(f.endPopulation)}.</p>`:'<p>Run one month to record births, deaths and migration.</p>'}${Math.abs(census.pendingChange)>.00001?'<p>Recent housing changes are included in the current age table; their migration is recorded at the next monthly check.</p>':''}<p>Age bands retain their history as residents age. Better health lowers modeled mortality. Occupied housing determines total residents; arrivals and departures reconcile demographic change with that total. Rates and initial ages are estimates for this reconstruction. Monthly flows represent averages and are rounded independently; the age table counts whole residents. Age distribution also affects workforce participation, education averages and education service demand.</p></details>`;}
